    /** Every item across every page of {@code GET /v1/connections/{id}/triggers}, fetched lazily (the cursor is followed for you). */
    public Iterable<ConnectionsListTriggersResponseDataItem> listTriggersAll(String id, ConnectionsListTriggersQuery query) {
        final ConnectionsListTriggersQuery base = query == null ? new ConnectionsListTriggersQuery() : query.copy();
        return Pagination.iterate(cursor -> {
            ConnectionsListTriggersResponse r = listTriggers(id, base.copy().startingAfter(cursor));
            return new CursorPage<>(r.data(), Boolean.TRUE.equals(r.hasMore()), (r.data() == null || r.data().isEmpty() ? null : r.data().get(r.data().size() - 1).id()));
        });
    }

    /** As above, with no query options. */
    public Iterable<ConnectionsListTriggersResponseDataItem> listTriggersAll(String id) {
        return listTriggersAll(id, null);
    }

